DO $$
DECLARE actor uuid; target uuid; foreign_user uuid; foreign_org bigint; org bigint; un bigint; a bigint; b bigint; result jsonb; cmd uuid; payload jsonb; order_id bigint; ticket_id bigint;
BEGIN
 PERFORM public.create_user_for_test('profile-fanout-manager','profile-fanout-manager@example.invalid');actor:=public.get_user_id('profile-fanout-manager');
 PERFORM public.create_user_for_test('profile-fanout-target','profile-fanout-target@example.invalid');target:=public.get_user_id('profile-fanout-target');
 INSERT INTO public.organizations(title) VALUES('Profile fanout') RETURNING id INTO org;
 UPDATE public.user_info SET organization=org WHERE id IN(actor,target);
 UPDATE public.user_info SET email_readonly='profile-fanout-target@example.invalid' WHERE id=target;
 INSERT INTO public.units(title,organization) VALUES('Profile fanout',org) RETURNING id INTO un;
 INSERT INTO public.unit_users(unit,"user",is_manager,is_editor) VALUES(un,actor,true,true);
 INSERT INTO public.occasions(title,organization,unit,link,start_time,end_time) VALUES('A',org,un,gen_random_uuid()::text,now(),now()+interval '1 day') RETURNING id INTO a;
 INSERT INTO public.occasions(title,organization,unit,link,start_time,end_time) VALUES('B',org,un,gen_random_uuid()::text,now(),now()+interval '1 day') RETURNING id INTO b;
 INSERT INTO public.occasion_users(occasion,"user",is_manager,is_editor) VALUES(a,actor,true,true),(b,actor,true,true),(a,target,false,false),(b,target,false,false);
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);
 payload:=jsonb_build_object('occasion',a,'user',target,'data',jsonb_build_object('name','Alice'));cmd:=gen_random_uuid();
 EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.save_profile_client_sync_v1(a,target,cmd,0,payload);ASSERT result->>'status'='applied';ASSERT public.save_profile_client_sync_v1(a,target,cmd,0,payload)=result;
 ASSERT public.save_profile_client_sync_v1(b,target,gen_random_uuid(),0,payload||jsonb_build_object('occasion',b,'data',jsonb_build_object('name','Stale')))->>'status'='conflict';
 payload:=payload||jsonb_build_object('occasion',b,'data',jsonb_build_object('name','Alice','note','Only local'));
 ASSERT public.save_profile_client_sync_v1(b,target,gen_random_uuid(),1,payload)->>'status'='applied';
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT version=1 FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_id=a AND aggregate_id=target::text),'local-only edit does not invalidate another occasion';
 ASSERT (SELECT version=2 FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_id=b AND aggregate_id=target::text);
 -- Unit-account scope shares identity columns but not occasion membership rights.
 EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.update_user(jsonb_build_object('unit',un,'user',target,'data',jsonb_build_object('surname','Unit update')));ASSERT result->>'code'='200';
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT version=2 FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_id=a AND aggregate_id=target::text);
 ASSERT (SELECT version=3 FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_id=b AND aggregate_id=target::text);
 cmd:=gen_random_uuid();payload:=jsonb_build_array(jsonb_build_object('user_id',target,'data',jsonb_build_object('email','profile-fanout-target@example.invalid','name','CSV name')));
 EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.import_profiles_client_sync_v1(a,cmd,payload,'[]');ASSERT result->>'status'='applied';ASSERT public.import_profiles_client_sync_v1(a,cmd,payload,'[]')=result;
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT version=3 FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_id=a AND aggregate_id=target::text);
 ASSERT (SELECT version=4 FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_id=b AND aggregate_id=target::text);
 INSERT INTO eshop.orders(occasion,order_sequence,order_symbol,state,data) VALUES(a,public.next_order_sequence(a),public.generate_order_symbol(),'paid',jsonb_build_object('email','profile-fanout-target@example.invalid','name','Ticket name')) RETURNING id INTO order_id;
 INSERT INTO eshop.tickets(occasion,state) VALUES(a,'paid') RETURNING id INTO ticket_id;
 INSERT INTO eshop.order_product_ticket("order",ticket) VALUES(order_id,ticket_id);
 UPDATE public.occasion_users SET ticket=ticket_id WHERE occasion=a AND "user"=target;
 cmd:=gen_random_uuid();EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.import_users_from_tickets_client_sync_v1(a,cmd);ASSERT result->>'status'='applied';ASSERT public.import_users_from_tickets_client_sync_v1(a,cmd)=result;
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT name='Ticket name' FROM public.user_info WHERE id=target);
 ASSERT (SELECT version=5 FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_id=b AND aggregate_id=target::text);
 PERFORM public.create_user_for_test('profile-fanout-foreign','profile-fanout-foreign@example.invalid');foreign_user:=public.get_user_id('profile-fanout-foreign');
 INSERT INTO public.organizations(title) VALUES('Foreign profile tenant') RETURNING id INTO foreign_org;
 UPDATE public.user_info SET organization=foreign_org WHERE id=foreign_user;
 EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.update_user(jsonb_build_object('unit',un,'user',foreign_user,'data',jsonb_build_object('name','Forbidden')));ASSERT result->>'code'='403';
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT name='Test' FROM public.user_info WHERE id=foreign_user),'unit account updates cannot cross tenant boundaries';
 ASSERT NOT has_function_privilege('authenticated','public.publish_user_profile_change_internal_v1(uuid,bigint,jsonb)','EXECUTE');
 ASSERT NOT has_function_privilege('authenticated','public.import_users_from_tickets(bigint)','EXECUTE');
 ASSERT NOT has_function_privilege('service_role','public.import_occasion_users_from_csv_apply_v1(bigint,jsonb,jsonb)','EXECUTE');
 ASSERT NOT has_table_privilege('authenticated','public.user_info','UPDATE');
 ASSERT NOT has_table_privilege('authenticated','public.occasion_users','UPDATE');
END $$;
